macro_rules! deps {
    () => {
        Operand!();
        Place!();
        SwitchTargets!();
        BasicBlockId!();
    };
}

macro_rules! TerminatorKind {
    () => {
        deps!();
        # [derive (Debug , PartialEq , Eq , Clone)] pub enum TerminatorKind < 'db > { # [doc = " Block has one successor; we continue execution there."] Goto { target : BasicBlockId < 'db > } , # [doc = " Switches based on the computed value."] # [doc = ""] # [doc = " First, evaluates the `discr` operand. The type of the operand must be a signed or unsigned"] # [doc = " integer, char, or bool, and must match the given type. Then, if the list of switch targets"] # [doc = " contains the computed value, continues execution at the associated basic block. Otherwise,"] # [doc = " continues execution at the \"otherwise\" basic block."] # [doc = ""] # [doc = " Target values may not appear more than once."] SwitchInt { # [doc = " The discriminant value being tested."] discr : Operand < 'db > , targets : SwitchTargets < 'db > , } , # [doc = " Indicates that the landing pad is finished and that the process should continue unwinding."] # [doc = ""] # [doc = " Like a return, this marks the end of this invocation of the function."] # [doc = ""] # [doc = " Only permitted in cleanup blocks. `Resume` is not permitted with `-C unwind=abort` after"] # [doc = " deaggregation runs."] UnwindResume , # [doc = " Indicates that the landing pad is finished and that the process should abort."] # [doc = ""] # [doc = " Used to prevent unwinding for foreign items or with `-C unwind=abort`. Only permitted in"] # [doc = " cleanup blocks."] Abort , # [doc = " Returns from the function."] # [doc = ""] # [doc = " Like function calls, the exact semantics of returns in Rust are unclear. Returning very"] # [doc = " likely at least assigns the value currently in the return place (`_0`) to the place"] # [doc = " specified in the associated `Call` terminator in the calling function, as if assigned via"] # [doc = " `dest = move _0`. It might additionally do other things, like have side-effects in the"] # [doc = " aliasing model."] # [doc = ""] # [doc = " If the body is a coroutine body, this has slightly different semantics; it instead causes a"] # [doc = " `CoroutineState::Returned(_0)` to be created (as if by an `Aggregate` rvalue) and assigned"] # [doc = " to the return place."] Return , # [doc = " Indicates a terminator that can never be reached."] # [doc = ""] # [doc = " Executing this terminator is UB."] Unreachable , # [doc = " The behavior of this statement differs significantly before and after drop elaboration."] # [doc = " After drop elaboration, `Drop` executes the drop glue for the specified place, after which"] # [doc = " it continues execution/unwinds at the given basic blocks. It is possible that executing drop"] # [doc = " glue is special - this would be part of Rust's memory model. (**FIXME**: due we have an"] # [doc = " issue tracking if drop glue has any interesting semantics in addition to those of a function"] # [doc = " call?)"] # [doc = ""] # [doc = " `Drop` before drop elaboration is a *conditional* execution of the drop glue. Specifically, the"] # [doc = " `Drop` will be executed if..."] # [doc = ""] # [doc = " **Needs clarification**: End of that sentence. This in effect should document the exact"] # [doc = " behavior of drop elaboration. The following sounds vaguely right, but I'm not quite sure:"] # [doc = ""] # [doc = " > The drop glue is executed if, among all statements executed within this `Body`, an assignment to"] # [doc = " > the place or one of its \"parents\" occurred more recently than a move out of it. This does not"] # [doc = " > consider indirect assignments."] Drop { place : Place < 'db > , target : BasicBlockId < 'db > , unwind : Option < BasicBlockId < 'db > > } , # [doc = " Drops the place and assigns a new value to it."] # [doc = ""] # [doc = " This first performs the exact same operation as the pre drop-elaboration `Drop` terminator;"] # [doc = " it then additionally assigns the `value` to the `place` as if by an assignment statement."] # [doc = " This assignment occurs both in the unwind and the regular code paths. The semantics are best"] # [doc = " explained by the elaboration:"] # [doc = ""] # [doc = " ```ignore (MIR)"] # [doc = " BB0 {"] # [doc = "   DropAndReplace(P <- V, goto BB1, unwind BB2)"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " becomes"] # [doc = ""] # [doc = " ```ignore (MIR)"] # [doc = " BB0 {"] # [doc = "   Drop(P, goto BB1, unwind BB2)"] # [doc = " }"] # [doc = " BB1 {"] # [doc = "   // P is now uninitialized"] # [doc = "   P <- V"] # [doc = " }"] # [doc = " BB2 {"] # [doc = "   // P is now uninitialized -- its dtor panicked"] # [doc = "   P <- V"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " Disallowed after drop elaboration."] DropAndReplace { place : Place < 'db > , value : Operand < 'db > , target : BasicBlockId < 'db > , unwind : Option < BasicBlockId < 'db > > , } , # [doc = " Roughly speaking, evaluates the `func` operand and the arguments, and starts execution of"] # [doc = " the referred to function. The operand types must match the argument types of the function."] # [doc = " The return place type must match the return type. The type of the `func` operand must be"] # [doc = " callable, meaning either a function pointer, a function type, or a closure type."] # [doc = ""] # [doc = " **Needs clarification**: The exact semantics of this. Current backends rely on `move`"] # [doc = " operands not aliasing the return place. It is unclear how this is justified in MIR, see"] # [doc = " [#71117]."] # [doc = ""] # [doc = " [#71117]: https://github.com/rust-lang/rust/issues/71117"] Call { # [doc = " The function that’s being called."] func : Operand < 'db > , # [doc = " Arguments the function is called with."] # [doc = " These are owned by the callee, which is free to modify them."] # [doc = " This allows the memory occupied by \"by-value\" arguments to be"] # [doc = " reused across function calls without duplicating the contents."] args : Box < [Operand < 'db >] > , # [doc = " Where the returned value will be written"] destination : Place < 'db > , # [doc = " Where to go after this call returns. If none, the call necessarily diverges."] target : Option < BasicBlockId < 'db > > , # [doc = " Cleanups to be done if the call unwinds."] cleanup : Option < BasicBlockId < 'db > > , # [doc = " `true` if this is from a call in HIR rather than from an overloaded"] # [doc = " operator. True for overloaded function call."] from_hir_call : bool , } , # [doc = " Evaluates the operand, which must have type `bool`. If it is not equal to `expected`,"] # [doc = " initiates a panic. Initiating a panic corresponds to a `Call` terminator with some"] # [doc = " unspecified constant as the function to call, all the operands stored in the `AssertMessage`"] # [doc = " as parameters, and `None` for the destination. Keep in mind that the `cleanup` path is not"] # [doc = " necessarily executed even in the case of a panic, for example in `-C panic=abort`. If the"] # [doc = " assertion does not fail, execution continues at the specified basic block."] Assert { cond : Operand < 'db > , expected : bool , target : BasicBlockId < 'db > , cleanup : Option < BasicBlockId < 'db > > , } , # [doc = " Marks a suspend point."] # [doc = ""] # [doc = " Like `Return` terminators in coroutine bodies, this computes `value` and then a"] # [doc = " `CoroutineState::Yielded(value)` as if by `Aggregate` rvalue. That value is then assigned to"] # [doc = " the return place of the function calling this one, and execution continues in the calling"] # [doc = " function. When next invoked with the same first argument, execution of this function"] # [doc = " continues at the `resume` basic block, with the second argument written to the `resume_arg`"] # [doc = " place. If the coroutine is dropped before then, the `drop` basic block is invoked."] # [doc = ""] # [doc = " Not permitted in bodies that are not coroutine bodies, or after coroutine lowering."] # [doc = ""] # [doc = " **Needs clarification**: What about the evaluation order of the `resume_arg` and `value`?"] Yield { # [doc = " The value to return."] value : Operand < 'db > , # [doc = " Where to resume to."] resume : BasicBlockId < 'db > , # [doc = " The place to store the resume argument in."] resume_arg : Place < 'db > , # [doc = " Cleanup to be done if the coroutine is dropped at this suspend point."] drop : Option < BasicBlockId < 'db > > , } , # [doc = " Indicates the end of dropping a coroutine."] # [doc = ""] # [doc = " Semantically just a `return` (from the coroutines drop glue). Only permitted in the same situations"] # [doc = " as `yield`."] # [doc = ""] # [doc = " **Needs clarification**: Is that even correct? The coroutine drop code is always confusing"] # [doc = " to me, because it's not even really in the current body."] # [doc = ""] # [doc = " **Needs clarification**: Are there type system constraints on these terminators? Should"] # [doc = " there be a \"block type\" like `cleanup` blocks for them?"] CoroutineDrop , # [doc = " A block where control flow only ever takes one real path, but borrowck needs to be more"] # [doc = " conservative."] # [doc = ""] # [doc = " At runtime this is semantically just a goto."] # [doc = ""] # [doc = " Disallowed after drop elaboration."] FalseEdge { # [doc = " The target normal control flow will take."] real_target : BasicBlockId < 'db > , # [doc = " A block control flow could conceptually jump to, but won't in"] # [doc = " practice."] imaginary_target : BasicBlockId < 'db > , } , # [doc = " A terminator for blocks that only take one path in reality, but where we reserve the right"] # [doc = " to unwind in borrowck, even if it won't happen in practice. This can arise in infinite loops"] # [doc = " with no function calls for example."] # [doc = ""] # [doc = " At runtime this is semantically just a goto."] # [doc = ""] # [doc = " Disallowed after drop elaboration."] FalseUnwind { # [doc = " The target normal control flow will take."] real_target : BasicBlockId < 'db > , # [doc = " The imaginary cleanup block link. This particular path will never be taken"] # [doc = " in practice, but in order to avoid fragility we want to always"] # [doc = " consider it in borrowck. We don't want to accept programs which"] # [doc = " pass borrowck only when `panic=abort` or some assertions are disabled"] # [doc = " due to release vs. debug mode builds. This needs to be an `Option` because"] # [doc = " of the `remove_noop_landing_pads` and `abort_unwinding_calls` passes."] unwind : Option < BasicBlockId < 'db > > , } , }
    };
}

TerminatorKind!()